function bestCrewOutput(speed: number[], efficiency: number[], k: number): number {
  let best = 0;
  for (let e = 0; e < speed.length; e++) {
    // e must be in the crew; the others need efficiency >= efficiency[e]
    const others: number[] = [];
    for (let j = 0; j < speed.length; j++) {
      if (j !== e && efficiency[j] >= efficiency[e]) others.push(speed[j]);
    }
    others.sort((a, b) => b - a);
    let sum = speed[e];
    for (let t = 0; t < Math.min(k - 1, others.length); t++) sum += others[t];
    best = Math.max(best, sum * efficiency[e]);
  }
  return best;
}

