class MinHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  push(x: number): void {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function bestCrewOutput(speed: number[], efficiency: number[], k: number): number {
  const order = speed.map((_, i) => i).sort((x, y) => efficiency[y] - efficiency[x]);
  const heap = new MinHeap();
  let sum = 0, best = 0;
  for (const i of order) {
    heap.push(speed[i]);
    sum += speed[i];
    if (heap.size > k) sum -= heap.pop();
    best = Math.max(best, sum * efficiency[i]);
  }
  return best;
}

